const icon = n => `<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n] || paths.spark}"/></svg>`;
const money = cents => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const day = new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'long',month:'long',day:'numeric'}).format(new Date());
const config = window.PERSEN_CONFIG || {};
const api = createDonnaAPI(config);
const browserStorage = name => {try{return window[name];}catch{return null;}};
const safeRead = (name,key,fallback) => {try{return JSON.parse(browserStorage(name)?.getItem(key) || 'null') ?? fallback;}catch{return fallback;}};
const commandCenterUrl = (() => {
  const target = typeof config.commandCenterUrl === 'string' && config.commandCenterUrl.trim()
    ? config.commandCenterUrl.trim() : config.donnaStaging ? '' : '../index.html';
  if (!target) return '';
  try {
    const url = new URL(target,location.href);
    const local = ['localhost','127.0.0.1','[::1]'].includes(url.hostname) && url.origin === location.origin;
    return !url.username && !url.password && (url.protocol === 'https:' || url.protocol === 'http:' && local) ? url.href : '';
  } catch { return ''; }
})();
const saveSession = () => {try{browserStorage('sessionStorage')?.setItem('donna.sandbox',JSON.stringify({messages:connected()?[]:state.messages,memories:state.localMemories,tasks:state.tasks,events:state.events}));}catch{toast('This browser could not keep session data. Export anything you need.');}};
const saved = safeRead('sessionStorage','donna.sandbox',{});
const state = {
  view:new URLSearchParams(location.search).get('view') || 'overview',
  auth:{authenticated:false,admin:false},generation:0,data:{},errors:{},memories:[],memoryComplete:true,conversationId:null,conversationTitle:'',conversationEpoch:0,dialogEpoch:0,sending:false,teaching:false,teachingDraft:null,localMemories:saved.memories||[],
  messages:saved.messages||[],tasks:saved.tasks||[],events:saved.events||[],busy:false,search:'',
  settings:{voiceMuted:false,...safeRead('localStorage','donna.settings',{theme:'light',voice:'',speak:false})},listening:false
};
document.documentElement.dataset.theme = state.settings.theme;
const nav = [
 ['overview','grid','Overview'],['voice','spark','Talk to Donna'],['teach','book','Teach Donna'],
 ['tasks','check',"Today's priorities"],['orders','bag','Orders'],['contacts','people','Customers'],
 ['invoices','invoice','Invoices'],['inventory','box','Inventory'],['events','calendar','Events & calendar'],
 ['memory','memory',"Donna's memory"],['pricing','calc','Pricing & profit'],['settings','settings','Settings']
];
const connected = () => Boolean(state.auth.authenticated && state.auth.admin);
const rows = tool => state.data[tool]?.rows || [];
const memories = () => connected()?state.memories:state.localMemories;
const pendingBadge = () => connected() ? '<span class="pill good"><span class="dot"></span>Owner signed in</span>' : '<span class="pill">Workspace preview</span>';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function setView(view){if(state.listening){try{recognition?.abort();}catch{}state.listening=false;}state.view=view;state.search='';const url=new URL(location.href);url.searchParams.set('view',view);history.pushState({},'',url);render();window.scrollTo({top:0,behavior:'smooth'});}
function orb(){return '<div class="orb-wrap" aria-hidden="true"><div class="orb-ring"></div><div class="orb-ring"></div><div class="orb"></div></div>';}
function shell(content){
 const selected=nav.find(x=>x[0]===state.view)?.[2] || (state.view==='briefing'?'Morning briefing':state.view==='shortcuts'?'Siri shortcuts':state.view==='private-chat'?'Donna Private Chat':'Donna');
 return `<aside class="sidebar" aria-label="Main navigation"><a href="?view=overview" class="brand" data-view="overview"><div class="brand-mark">d</div><div><strong>donna</strong><div class="eyebrow">PERSEN APPAREL</div></div></a><div class="nav-label">YOUR ASSISTANT</div>${nav.slice(0,3).map(navLink).join('')}<div class="nav-label">YOUR BUSINESS</div>${nav.slice(3,9).map(navLink).join('')}<div class="nav-label">PERSONAL WORKSPACE</div>${nav.slice(9).map(navLink).join('')}<div class="side-bottom"><div class="budget"><strong><span class="dot"></span>Thoughtful by design.</strong>No paid AI services enabled.</div><div class="profile"><div class="avatar">PA</div><div><strong>Persen Apparel</strong><span>${connected()?'Owner workspace':'Private business assistant'}</span></div><button data-action="login" aria-label="Account settings">${icon('settings')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><span class="muted mobile-hide">Your workspace</span><span class="slash mobile-hide">/</span><span>${esc(selected)}</span></div><div class="top-actions"><span>Made for your day. Ready when you are.</span>${pendingBadge()}<button class="icon-btn" data-action="theme" aria-label="Toggle color theme">${icon('sun')}</button></div></header><main id="main">${content}<footer class="footer"><span>${icon('lock')} Your business stays yours. No cloud AI connected.</span><span>Sweet in how we speak. Straightforward in what we say.</span></footer></main></div>`;
}
function navLink([view,i,label]){return `<a href="?view=${view}" data-view="${view}" class="nav-item ${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`;}
function head(eyebrow,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action||`<div class="date-label">${icon('calendar')}${esc(day)}</div>`}</div>`;}
function connectionCard(){return `<section class="card rail-card"><div class="section-title"><h2>Your business, connected.</h2>${icon('link')}</div><p>${connected()?'Donna can read the records your owner account is allowed to access.':'Bring your real orders, priorities, and inventory into the conversation.'}</p><div class="connection-illustration"><div class="mini-logo">d</div><div class="connection-dots">···</div><div class="mini-logo">P.</div></div><div class="connection-info"><span class="dot"></span>${connected()?'Command Center · read-only access':'Command Center · not connected'}</div><button class="btn full" data-action="${connected()?'refresh':'login'}">${icon(connected()?'check':'lock')}${connected()?'Refresh business records':'Connect Command Center'}</button><p class="small" style="font-size:9px;margin-top:12px;text-align:center">${connected()?'No business records can be changed here.':'Sign in with your existing owner account.'}</p></section>`;}
function siriCard(){return `<div class="siri-note">${icon('spark')}<div><h3>Just say, “Hey Siri, Donna.”</h3><p>Your assistant is a shortcut away.<br><a href="?view=shortcuts" data-view="shortcuts" class="link">Set up your Siri shortcuts ${'↗'}</a></p></div></div>`;}
function noRecords(tool,description=''){return `<div class="empty">${icon(tool==='inventory'?'box':'lock')}<h3>${state.errors[tool]?'Could not load this information':connected()?'No records returned':'Your business records will appear here.'}</h3><p>${esc(state.errors[tool] || description || (connected()?'This view contains only authorized records.':'Connect Command Center to see current, verified information.'))}</p>${!connected()?'<button class="btn text" data-action="login">Connect your account '+icon('arrow')+'</button>':''}</div>`;}
function overview(){
 const briefs=buildBriefing(state.data,new Date()).items||[];
 const openTasks=rows('tasks').filter(t=>!['Done','Completed','Cancelled'].includes(t.status));
 const openOrders=rows('orders').filter(t=>!['Completed','Cancelled'].includes(t.status));
 const lowStock=rows('inventory').filter(t=>Number(t.quantity)<=Number(t.reorder_at));
 const metric=(label,n,i,tool)=>`<div class="card stat"><div class="stat-title">${label}${icon(i)}</div><strong>${state.data[tool]?n:'—'}</strong><span class="small">${state.data[tool]?(state.data[tool].complete?'From current records':'Loaded records · partial'):state.errors[tool]?'Unavailable':'Connect to see your records'}</span></div>`;
 return head('A little clarity, every day.','Good to see you.','Let’s make room for what matters at Persen Apparel.')+`<div class="dashboard-grid"><div><section class="card hero"><div class="hero-content"><div class="eyebrow">YOUR PERSEN APPAREL BUSINESS ASSISTANT</div><h2>Hey! What can I<br>help you with today?</h2><p>A busy day feels a little lighter with someone in your corner. Let’s take it one thing at a time.</p><div class="hero-buttons"><button class="btn primary" data-view="voice">${icon('mic')}Talk to Donna</button><button class="btn text" data-view="chat">Or start a chat ${icon('arrow')}</button></div></div>${orb()}<div class="hero-orb-label" style="right:43px;bottom:27px"><span class="dot"></span>HERE TO HELP YOU</div></section><div class="stats">${metric('Open priorities',openTasks.length,'check','tasks')}${metric('Orders in progress',openOrders.length,'bag','orders')}${metric('Low-stock items',lowStock.length,'box','inventory')}</div><section><div class="section-title"><h2>A good place to start</h2><span class="muted small" style="font-size:9px">A little help goes a long way.</span></div><div class="quick-grid">${[['briefing','sun','Your morning briefing','A clear view of what needs your attention today.'],['teach','book','Teach me something','Help me learn how you like to run your business.'],['pricing','calc','Let’s check the numbers','Work out your costs, profit, and pricing together.']].map(([v,i,t,p])=>`<button class="card quick" data-view="${v}"><div class="quick-icon">${icon(i)}</div><h3>${t}</h3><p>${p}</p>${icon('arrow').replace('<svg','<svg class="arrow"')}</button>`).join('')}</div></section><section class="priorities-section"><div class="section-title"><h2>A little focus for today</h2><button data-view="tasks">View priorities ${icon('arrow')}</button></div><div class="card">${briefs.length?briefs.slice(0,3).map(priorityRow).join(''):noRecords('tasks',connected()?'No alerts were found in the loaded records.':'Your deadlines and follow-ups, in one calm place. No records have been loaded yet.')}</div></section></div><div class="rail">${connectionCard()}<section class="card rail-card memory-teaser"><div class="eyebrow">GETTING TO KNOW YOUR BUSINESS</div><h2>A little more you, every day.</h2><div class="note">“When a customer asks for a quote, collect the product, sizes, quantity, and artwork first.”</div><p>An example of a process you can teach me. I’ll ask you to review it before remembering.</p><button class="btn text" data-view="teach" style="margin-top:14px">Teach Donna ${icon('arrow')}</button></section>${siriCard()}</div></div>`;
}
function priorityRow(x){return `<div class="priority-row"><div class="priority-icon">${icon(x.kind==='invoice'?'invoice':x.kind==='inventory'?'box':'check')}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.detail||'')}</p></div><span class="pill">${esc(x.priority===3?'High priority':x.kind||'Personal')}</span></div>`;}
function chatView(voice=false){return head('A little space to think.',voice?'I’m here. Let’s talk.':'Let’s work through it together.','Your free web workspace uses business tools and approved memory. Native Donna adds on-device AI.')+`<div class="view-grid"><div class="card chat-shell"><div class="form-actions" style="padding:17px 22px 0;margin-top:0"><button class="btn" data-action="new-conversation" ${state.sending?'disabled':''}>${icon('plus')}New conversation</button><button class="btn" data-action="saved-conversations" ${state.sending?'disabled':''}>${icon('book')}Saved conversations</button>${state.conversationId?'<span class="pill good">Saved transcript</span>':''}</div>${voice?`<div class="voice-stage">${orb()}<h2>Hey! What can I help you with today?</h2><p>Tap to talk. After you finish speaking, Donna sends your words. Voice replies play automatically unless muted. Browser microphone transcription may use an external speech service. This web version uses business rules, not open-ended AI.</p><div class="voice-status" id="voice-status" role="status">${state.listening?'Listening… tap to finish.':'Ready when you are.'}</div><button class="mic-button ${state.listening?'listening':''}" data-action="mic" aria-pressed="${state.listening?'true':'false'}" aria-controls="voice-status" aria-label="${state.listening?'Finish voice input':'Start voice input'}">${icon('mic')}</button><div class="form-actions" style="justify-content:center"><button type="button" class="btn" data-action="speak-last" aria-label="Play last Donna reply">${icon('speaker')}Play reply</button><button type="button" class="btn" data-action="stop-speech" aria-label="Stop Donna speaking">Stop speaking</button><button type="button" class="btn" data-action="toggle-voice-mute" aria-pressed="${state.settings.voiceMuted?'true':'false'}" aria-label="${state.settings.voiceMuted?'Unmute automatic voice replies':'Mute automatic voice replies'}">${state.settings.voiceMuted?'Unmute replies':'Mute replies'}</button></div></div>`:''}<div class="messages" aria-label="Conversation transcript" aria-live="polite">${state.messages.length?state.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${m.role==='assistant'?'<div class="byline">'+icon('spark')+' DONNA · BUSINESS TOOLS</div>':''}${esc(m.text)}</div>`).join(''):!voice?'<div class="message"><div class="byline">'+icon('spark')+' DONNA</div>Hey! We can check your priorities, learn a business process, or work through pricing. What would you like to start with?</div>':''}</div><div class="prompts">${state.teachingDraft?'<button class="prompt" data-action="review-teaching">Review teaching draft</button>':''}${['What are my priorities?','Check inventory','I want to teach you something'].map(t=>`<button class="prompt" data-prompt="${esc(t)}">${esc(t)}</button>`).join('')}</div><form class="chat-compose" id="chat-form"><button type="button" class="icon-btn" data-action="mic" aria-label="Start voice input" ${voice?'aria-controls="voice-status"':''}>${icon('mic')}</button><textarea name="message" rows="1" aria-label="Message Donna" placeholder="What’s on your mind?" maxlength="6000" required></textarea><button class="btn primary" type="submit" ${state.busy||state.sending?'disabled':''}>${icon('send')}<span>Send</span></button></form></div><aside class="rail"><div class="card rail-card"><h2>Honest help. Clear boundaries.</h2><p style="margin-top:13px">I can look up verified records, use your approved procedures, and help calculate pricing. Free web mode is a set of reliable business tools, with limited conversational understanding.</p><div class="connection-info">${icon('lock')}No conversation goes to a cloud AI provider.</div><p>For flexible, on-device conversation, use the native iPhone build once it has been tested on your device.</p><button class="btn text" data-view="settings">Voice & privacy settings ${icon('arrow')}</button></div>${connectionCard()}</aside></div>`;}
function teachView(){return head('Made to learn your way.','Teach me how you do things.','Your processes, preferences, and good ideas — reviewed by you before I remember.')+`<div class="view-grid"><section class="card content-card"><div class="notice">${connected()?'New knowledge is saved as a draft. Review and approve it in Donna’s memory.':'Session practice · Teaching works here, but drafts stay in this browser tab. Connect and install the memory schema for private, persistent storage.'}</div><form id="teach-form" class="form-grid"><div class="field wide"><label for="memory-title">What would you like to teach me?</label><input id="memory-title" name="title" maxlength="160" placeholder="e.g. Our standard quote process" required></div><div class="field"><label for="category">Category</label><select name="category" id="category">${MEMORY_CATEGORIES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="source">Source</label><input name="source" id="source" value="Owner teaching" maxlength="300" required></div><div class="field wide"><label for="lesson">Tell me in your own words</label><textarea id="lesson" name="content" maxlength="6000" placeholder="When a customer asks for a quote, I need to know…" required></textarea><small>You can use your iPhone keyboard’s microphone to dictate. Save only information Donna needs.</small></div><div class="field wide"><button class="btn primary" type="submit">${icon('book')}Prepare for my review</button></div></form></section><aside class="rail"><div class="card rail-card memory-teaser"><h2>We’ll get it right together.</h2><p style="margin-top:15px">I’ll keep the words you give me, with their source and timestamp. You can correct a draft, approve it, or mark it outdated.</p><div class="note">For a quote, consider product, color, sizes, quantity, artwork, design placement, and the deadline.</div><p>This adds approved knowledge for retrieval. It does not retrain Apple’s model.</p><button class="btn text" data-view="memory">Review my memory ${icon('arrow')}</button></div></aside></div>`;}
function memoryView(){const all=memories().filter(m=>`${m.title} ${m.content} ${m.category}`.toLowerCase().includes(state.search.toLowerCase()));return head('A shared understanding.',"Donna’s memory.",'Useful knowledge, saved with your approval. You’re always in control.',`<button class="btn primary" data-view="teach">${icon('plus')}Teach Donna</button>`)+`<div class="notice">${connected()?('Only confirmed memories are used as business knowledge. Suggestions and outdated information remain separate.'+(state.memoryComplete?'':' Partial results: some memories are not loaded.')):'Session practice · These memories are not synced and will be lost when this tab is cleared. Avoid private customer details.'}</div><div class="toolbar"><input id="memory-search" aria-label="Search memories" placeholder="Search procedures, preferences, and decisions…" value="${esc(state.search)}"><button class="btn" data-action="export">Export my data</button></div><div class="card" id="memory-list">${all.length?all.map(m=>`<article class="memory-item"><span class="pill ${m.status==='confirmed'?'good':''}">${esc(m.status)}</span><h3>${esc(m.title)}</h3><p>${esc(m.content)}</p><div class="memory-meta"><span>${esc(m.category)}</span>·<span>Source: ${esc(m.source)}</span>·<span>v${esc(m.version||1)}</span>·<span>${esc(new Date(m.updated_at||m.created_at).toLocaleString())}</span></div><div class="form-actions">${m.status==='pending'?`<button class="btn primary" data-memory="approve" data-id="${esc(m.id)}">Review & approve</button>`:''}<button class="btn" data-memory="edit" data-id="${esc(m.id)}">Correct</button><button class="btn" data-memory="history" data-id="${esc(m.id)}">History</button>${m.status!=='outdated'?`<button class="btn" data-memory="outdated" data-id="${esc(m.id)}">Mark outdated</button>`:''}<button class="btn danger" data-memory="delete" data-id="${esc(m.id)}">Delete</button></div></article>`).join(''):`<div class="empty">${icon('book')}<h3>${state.search?'No matching memories.':'A fresh start, with room to learn.'}</h3><p>Teach me your first business process when you’re ready.</p><button class="btn text" data-view="teach">Teach Donna ${icon('arrow')}</button></div>`}</div>`;}
const columns={orders:[['title','Project'],['customer_name','Customer'],['status','Status'],['due_date','Deadline']],inventory:[['product_name','Product'],['sku','SKU'],['color','Color'],['size','Size'],['quantity','Stock'],['reorder_at','Reorder at']],contacts:[['full_name','Customer'],['organization','Organization'],['email','Email'],['phone','Phone']],invoices:[['invoice_number','Document'],['customer_name','Customer'],['document_type','Type'],['total','Total ($)'],['status','Status'],['due_date','Due']],tasks:[['title','Task'],['customer_name','Customer'],['priority','Priority'],['status','Status'],['due_date','Due']]};
function recordsView(tool){const title={orders:'A clear view of every order.',inventory:'Know what’s on your shelves.',contacts:'Your people, all together.',invoices:'Keep the paperwork in focus.'}[tool];const list=rows(tool).filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(state.search.toLowerCase())));return head('Your business, in focus.',title,'Read-only Command Center records. Changes stay in your existing business tools.',`<button class="btn" data-action="refresh">${icon('link')}Refresh records</button>`)+`<div class="notice">${state.data[tool]?esc(state.data[tool].source||'Command Center')+' · Loaded '+esc(state.data[tool].asOf||'now')+' · '+(state.data[tool].complete?'All matching records loaded.':'Partial results. Counts and totals do not represent your full business.'):'Connect your owner account to retrieve real information. No example business records are displayed.'}</div>${tool==='invoices'?'<div class="notice warning">Invoice totals are documents, not collected revenue or profit. Payment lookups are available in chat; the web version does not estimate profit from missing costs.</div>':''}<div class="toolbar"><input id="record-search" aria-label="Search loaded records" placeholder="Search loaded records…" value="${esc(state.search)}">${commandCenterUrl?`<a class="btn" href="${esc(commandCenterUrl)}" target="_blank" rel="noopener">Open Command Center ${icon('arrow')}</a>`:''}</div><div class="card">${list.length?table(list,columns[tool]):noRecords(tool)}</div>`;}
function table(list,cols){return `<div class="data-table-wrap"><table class="data-table"><thead><tr>${cols.map(x=>`<th scope="col">${x[1]}</th>`).join('')}</tr></thead><tbody>${list.map(x=>`<tr>${cols.map(([k])=>`<td>${esc(x[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function tasksView(briefing=false){const briefs=buildBriefing(state.data,new Date());return head(briefing?'A calmer start.':'One thing at a time.',briefing?'Your morning, with a little clarity.':'Let’s focus on what matters.',briefing?'Deadlines, follow-ups, and low-stock alerts from your authorized records.':'Business priorities stay read-only. Add a personal plan for this browser session.',`<button class="btn primary" data-action="add-task">${icon('plus')}Plan a task</button>`)+`<div class="view-grid"><div><div class="notice">${connected()?'Briefing computed from the loaded records, using America/New_York dates.':'Business data is not connected. Donna cannot assess your real deadlines or follow-ups yet.'} ${Object.values(state.data).some(d=>!d.complete)?'Some results are partial.':''}</div><section class="card"><div class="section-title" style="padding:22px 22px 0"><h2>${briefing?'Needs your attention':'Business priorities'}</h2><button data-action="refresh">Refresh</button></div>${briefs.items?.length?briefs.items.map(priorityRow).join(''):noRecords('tasks',connected()?'No alerts were found in the loaded records.':'Your current priorities appear after you connect.')}</section><section class="card" style="margin-top:20px"><div class="section-title" style="padding:22px 22px 0"><h2>My session plan</h2><span class="muted small">Private to this tab</span></div>${state.tasks.length?state.tasks.map(t=>`<div class="priority-row"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}"><div><strong style="${t.done?'text-decoration:line-through':''}">${esc(t.title)}</strong><p>${esc(t.due||'No deadline set')} · ${esc(t.priority)}</p></div><button class="btn text" data-remove-task="${esc(t.id)}" aria-label="Delete ${esc(t.title)}">${icon('close')}</button></div>`).join(''):'<div class="empty"><p>What’s one manageable thing you can do next?</p><button class="btn text" data-action="add-task">Add to my plan '+icon('plus')+'</button></div>'}</section></div><aside class="rail"><div class="card rail-card"><h2>A plan that leaves room for you.</h2><p style="margin-top:15px">Start with urgent deadlines, then choose one production block and one follow-up. Leave space around school and other commitments.</p><div class="connection-info">${icon('calendar')}Weekday briefing idea · 6:30 AM Eastern</div><p>Automatic briefings and notifications are disabled. A Siri shortcut can open this view whenever you’re ready.</p><button class="btn text" data-view="shortcuts">Set up morning shortcut ${icon('arrow')}</button></div></aside></div>`;}
function eventsView(){return head('Leave a little room.','Make space for what’s coming.','Plan events in this tab. Nothing is added to your phone’s calendar without you.',`<button class="btn primary" data-action="add-event">${icon('plus')}Plan an event</button>`)+`<div class="notice">Session planning · Command Center event profiles are read-only. Phone calendar sync is not connected. Export a session event and review it before adding it on your iPhone.</div><section class="card" style="margin-bottom:22px"><div class="section-title" style="padding:22px 22px 0"><h2>Command Center event profiles</h2><button data-action="refresh">Refresh</button></div>${rows('events').length?table(rows('events'),[['name','Event'],['event_date','Date'],['active','Active']]):noRecords('events')}</section><div class="section-title"><h2>My session events</h2></div><div class="card">${state.events.length?state.events.sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="priority-row"><div class="priority-icon">${icon('calendar')}</div><div><strong>${esc(e.title)}</strong><p>${esc(e.date)} · ${esc(e.notes||'All-day event')}</p></div><button class="btn" data-export-event="${esc(e.id)}">Export .ics</button><button class="btn text" data-remove-event="${esc(e.id)}" aria-label="Delete event">${icon('close')}</button></div>`).join(''):'<div class="empty">'+icon('calendar')+'<h3>A little space to plan ahead.</h3><p>Add a vendor event, production deadline, or customer pickup to your session plan.</p></div>'}</div>`;}
function pricingView(){const fields=[['price','Selling price'],['quantity','Quantity'],['garment','Blank garment'],['transfer','Transfer / decoration'],['labor','Labor'],['packaging','Packaging'],['shipping','Allocated shipping'],['fees','Fixed fees'],['overhead','Allocated overhead'],['feePercent','Payment fee (%)']];return head('Good decisions start with real numbers.','Let’s make your pricing work.','Understand the cost, profit, and margin before you commit.')+`<div class="view-grid"><section class="card content-card"><div class="notice">Enter every per-unit cost. Use 0 only when a cost does not apply. Sales tax is excluded; these estimates depend on the costs you provide.</div><form id="pricing-form" class="form-grid">${fields.map(([k,t])=>`<div class="field"><label for="price-${k}">${t}${!['quantity','feePercent'].includes(k)?' ($)':''}</label><input id="price-${k}" name="${k}" type="number" inputmode="${k==='quantity'?'numeric':'decimal'}" min="${k==='quantity'?'1':'0'}" step="${k==='quantity'?'1':'0.01'}" ${k==='quantity'?'value="1"':k==='feePercent'?'value="0"':''} max="${k==='quantity'?'100000':'1000000'}" required></div>`).join('')}<div class="wide"><button class="btn primary" type="submit">${icon('calc')}Calculate pricing</button></div></form><div id="pricing-result" aria-live="polite"></div></section><aside class="rail"><div class="card rail-card"><h2>Revenue isn’t profit.</h2><p style="margin-top:14px">Your price needs to cover more than the blank and transfer. Include your time, packaging, fees, and a fair share of overhead.</p><div class="note" style="padding:15px 0;color:var(--accent);font-size:12px;line-height:1.9">Profit = revenue − costs<br>Margin = profit ÷ revenue<br>Markup = profit ÷ cost</div><p>Calculations use integer cents and explicit inputs. This tool never invents a missing cost or uses AI for the arithmetic.</p></div></aside></div>`;}
function settingsView(){return head('Make yourself comfortable.','Your Donna, your preferences.','Control the voice, appearance, privacy, and cost boundaries of your workspace.')+`<section class="card content-card"><h2>Voice & appearance</h2><div class="setting-row"><div><h3>System voice</h3><p>Available voices depend on this device. Choose the voice you prefer.</p></div><select id="voice-select" aria-label="System voice"><option value="">Device default</option>${(window.speechSynthesis?.getVoices()||[]).map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===state.settings.voice?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('')}</select></div><div class="setting-row"><div><h3>Speak Donna’s replies</h3><p>Playback may require a tap on iPhone. Speech privacy depends on your system voice.</p></div><input type="checkbox" id="speak-toggle" ${state.settings.speak?'checked':''} aria-label="Speak replies"></div><div class="setting-row"><div><h3>Try your voice</h3><p>Listen to a short greeting using the selected system voice.</p></div><button class="btn" data-action="test-voice">${icon('speaker')}Play greeting</button></div><div class="setting-row"><div><h3>Color theme</h3><p>Choose the appearance that feels comfortable.</p></div><select id="theme-select" aria-label="Color theme"><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option></select></div><h2 style="margin-top:28px">Privacy & cost controls</h2><div class="notice" style="margin-top:15px">This tab: ${api.diagnostics?.().networkRequests??0} network requests · ${api.diagnostics?.().storageWrites??0} Donna storage requests · ${api.diagnostics?.().rateLimitResponses??0} rate-limit responses. These are session counters, not provider usage or billing totals.</div>${[['AI provider','Web business tools only. No cloud model or paid fallback.'],['On-device intelligence','Use the native app or set up Donna Private Chat with Apple Shortcuts. iPhone verification is still required.'],['Calls, messaging & publishing','Disabled. No autonomous calls, sending, purchases, or business record writes.'],['Notifications & scheduling','Disabled. Your briefing runs when you open it.'],['Business data access','Supabase owner authentication and row-level security. Read-only business tools.'],['Memory storage',connected()?'Private Supabase tables after the reviewed schema is installed.':'Session practice only until you sign in. No private records are cached offline.']].map(([t,p])=>`<div class="setting-row"><div><h3>${t}</h3><p>${esc(p)}</p></div><span class="pill">${['Calls, messaging & publishing','Notifications & scheduling'].includes(t)?'Off':'Configured'}</span></div>`).join('')}<div class="form-actions"><button class="btn" data-action="export">Export conversations & memory</button><button class="btn danger" data-action="delete-data">Delete Donna data</button><button class="btn" data-action="${connected()?'signout':'login'}">${connected()?'Sign out':'Connect owner account'}</button></div><div class="notice" style="margin-top:24px">Target: $0 in new monthly costs. Existing Supabase and Cloudflare usage shares their provider allowances. Provider billing and quotas must be checked in their dashboards; this app cannot verify your account’s remaining allowance.</div><a class="link small" href="../docs/donna/CHATGPT-SHORTCUT.md" target="_blank" rel="noopener noreferrer">Talk naturally with ChatGPT via a separate iPhone Shortcut (optional; not connected to live records) ${icon('arrow')}</a><br><br><a class="link small" href="?view=private-chat" data-view="private-chat">Set up Donna Private Chat with Apple’s on-device model ${icon('arrow')}</a><br><br><a class="link small" href="../docs/donna/SETUP-AND-COSTS.md" target="_blank" rel="noopener">Setup, verified free-tier limits, and device testing guide ↗</a></section>`;}
function shortcutsView(){const base=new URL('./',location.href);base.search='';base.hash='';const shortcuts=[['Donna','voice'],['Donna morning briefing','briefing'],['Teach Donna','teach'],["Donna’s tasks",'tasks'],['Donna inventory','inventory'],['Donna business overview','overview']];return head('A familiar voice. A helpful shortcut.','“Hey Siri, Donna.”','Use Apple Shortcuts to open your workspace. Siri launches Donna; you control the microphone.')+`<div class="view-grid"><section class="card content-card"><div class="notice warning">Use the final HTTPS staging or production address after you approve deployment. This address is not an installed iPhone shortcut. Launching will not bypass sign-in or start recording.</div><h2>Create your first shortcut</h2><div class="steps"><div class="step"><div><strong>Open Shortcuts on your iPhone.</strong>Tap +, then choose Add Action.</div></div><div class="step"><div><strong>Find and add “Open URLs”.</strong>Use your approved Donna address:<br><code>${esc(base.href)}?view=voice</code></div></div><div class="step"><div><strong>Name the shortcut “Donna”.</strong>Save it, then say “Hey Siri, Donna.” Unlock your phone and sign in when asked.</div></div><div class="step"><div><strong>Tap the microphone, or use keyboard dictation.</strong>Donna never listens in the background. Voice behavior must be checked on your iPhone 16.</div></div></div><h2 style="margin-top:30px">The rest of your shortcuts</h2>${table(shortcuts.map(([name,v])=>({name,url:base.href+'?view='+v})),[['name','Shortcut name'],['url','Open URLs address']])}</section><aside class="rail"><div class="card rail-card"><h2>Try private on-device chat.</h2><p style="margin-top:14px">Apple Shortcuts can run Donna Private Chat using its On-Device model on supported iPhones. It has no connection to your business records or saved memory.</p><p style="margin-top:12px"><a class="link" href="?view=private-chat" data-view="private-chat">Follow the iPhone setup guide ${icon('arrow')}</a></p><h2 style="margin-top:24px">Keep your business private.</h2><p style="margin-top:14px">Use a URL-opening shortcut, not a shortcut that embeds customer records or credentials. Require unlocking and owner sign-in before accessing business information.</p><p style="margin-top:12px">For an app-like experience, open Donna in Safari and choose Share → Add to Home Screen. Business data is not cached for offline use.</p></div></aside></div>`;}
function privateChatView(){
 return head('A private way to think things through.','Set up Donna Private Chat.','Use Apple’s On-Device model in Shortcuts on your iPhone 16. No Mac or custom app build is needed.')+`<div class="view-grid"><section class="card content-card"><div class="notice warning">Setup guide only · This shortcut has not been created, installed, or tested on your iPhone. This page does not run AI or install anything.</div><h2>Build the shortcut on your iPhone</h2><div class="steps"><div class="step"><div><strong>Check Apple Intelligence is ready.</strong>Unlock your iPhone and open Settings → Apple Intelligence &amp; Siri. Let the model download finish. Your reported iOS 27.0.1 supports the baseline; an update is not required solely for this setup.</div></div><div class="step"><div><strong>Create “Donna Private Chat”.</strong>In Shortcuts, tap +, name the shortcut, and add <b>Ask for Input</b> with Text input. Use the question: <i>Hey! What can I help you with today?</i> Leave the default answer empty.</div></div><div class="step"><div><strong>Add Use Model and explicitly choose On-Device.</strong>Choose Text output when offered and leave Follow Up off for the first test. Do not choose a cloud or extension model. If On-Device is unavailable, stop and keep using Donna’s web tools.</div></div><div class="step"><div><strong>Paste Donna’s prompt below.</strong>In Use Model’s prompt, replace <code>[YOUR QUESTION VARIABLE]</code> with the <b>Provided Input</b> / <b>Ask for Input</b> variable using the variable picker. Insert a variable token; do not leave the literal bracketed phrase.</div></div><div class="step"><div><strong>Show the Response.</strong>Add <b>Show Content</b>, or Show Result if that is the available text-display action, and select Use Model’s Response. Optional: add <b>Speak Text</b> using that same Response, choose an available voice, and retain the text display after it.</div></div><div class="step"><div><strong>Test with a small, harmless question.</strong>Tap Run and try: <i>I have 45 minutes after school. Help me plan one small task.</i> Confirm On-Device stays selected. After the model is downloaded, test a typed question by tapping the shortcut with networking disabled; Siri is a separate check.</div></div></div><div class="field" style="margin-top:28px"><label for="private-chat-prompt">Donna’s prompt for Use Model</label><textarea id="private-chat-prompt" readonly rows="19" aria-describedby="private-chat-copy-help">${esc(PRIVATE_CHAT_PROMPT)}</textarea><small id="private-chat-copy-help">Copy this public setup prompt, then replace the question placeholder with the input variable in Shortcuts. No credentials belong in it.</small></div><div class="form-actions"><button class="btn primary" data-action="copy-private-chat-prompt">${icon('book')}Copy prompt</button><button class="btn" data-view="shortcuts">Back to Siri shortcuts</button></div><p class="small muted" style="margin-top:22px">Source: <a class="link" href="https://support.apple.com/guide/shortcuts/use-apple-intelligence-in-shortcuts-tpg3vrvwmclv/ios" target="_blank" rel="noopener noreferrer">Apple’s guide to Apple Intelligence in Shortcuts ↗</a>. <a class="link" href="../docs/donna/ON-DEVICE-SHORTCUT.md" target="_blank" rel="noopener noreferrer">Full researched instructions and acceptance checklist ↗</a>.</p></section><aside class="rail"><section class="card rail-card"><h2>Suggestions, without business access.</h2><p style="margin-top:14px">This optional shortcut can help brainstorm and organize what you type. It has no Command Center connection, current orders, inventory, approved memory, financial engine, or cross-run conversation store.</p><div class="connection-info">${icon('lock')}Choose On-Device. No cloud fallback.</div><p>For pricing or verified business information, open Donna’s web tools. Keep confidential records out of this recipe until you have checked the phone’s privacy behavior.</p><h2 style="margin-top:24px">Add voice after text works.</h2><p style="margin-top:12px">You may dictate with the keyboard’s microphone, but on-device model selection does not guarantee that Siri or every speech-input path is local. Check Dictation privacy separately. A particular female voice is not guaranteed.</p><p style="margin-top:14px">Once your tests pass, try “Hey Siri, Donna Private Chat.” Test while unlocked first. You can optionally enable Use Model’s Follow Up for refinement during that run.</p><p style="margin-top:14px">No paid API, subscription, developer membership, call, message, or automatic schedule is enabled by this page.</p></section></aside></div>`;
}
async function copyPrivateChatPrompt(){
 const input=$('#private-chat-prompt');if(!input)return;
 try{
  if(typeof navigator.clipboard?.writeText!=='function')throw Error('Clipboard unavailable');
  await navigator.clipboard.writeText(PRIVATE_CHAT_PROMPT);
  toast('Donna’s prompt copied. Paste it in Use Model, then insert your question variable.');
 }catch{
  if(!input.isConnected)return;
  input.focus();input.select();input.setSelectionRange(0,input.value.length);
  toast('Prompt selected. Touch and hold the highlighted text, then choose Copy.');
 }
}
function render(){const view=state.view;const content=view==='overview'?overview():view==='voice'||view==='chat'?chatView(view==='voice'):view==='teach'?teachView():view==='memory'?memoryView():view==='tasks'||view==='briefing'?tasksView(view==='briefing'):view==='events'?eventsView():view==='pricing'?pricingView():view==='settings'?settingsView():view==='shortcuts'?shortcutsView():view==='private-chat'?privateChatView():columns[view]?recordsView(view):overview();$('#app').innerHTML=shell(content);if(['chat','voice'].includes(view))$('.messages')?.scrollTo({top:999999});}
async function loadRecords(){
 if(!connected())return;
 const generation=state.generation;state.busy=true;toast('Reading your authorized business records…');
 const result=await Promise.all(['tasks','orders','inventory','contacts','invoices','payments','agreements','events'].map(async tool=>{try{return {tool,data:await api.load(tool)};}catch(e){return {tool,error:e.message};}}));
 if(generation!==state.generation||!connected())return;
 for(const entry of result){if(entry.error){state.errors[entry.tool]=entry.error;delete state.data[entry.tool];}else{state.data[entry.tool]=entry.data;delete state.errors[entry.tool];}}
 try{const memory=await api.memories.list();if(generation!==state.generation||!connected())return;state.memories=memory.rows;state.memoryComplete=memory.complete;}
 catch(e){if(generation!==state.generation)return;state.memories=[];toast('Business access is ready. Memory needs setup: '+e.message);}
 state.busy=false;render();
}
function modal(html){state.dialogEpoch++;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){state.dialogEpoch++;$('#modal').close();}
function loginModal(){if(state.auth.configured===false){modal('<h2>This workspace is disconnected.</h2><p>Teaching practice, planning, and pricing work without an account. A separate test backend must be configured before signing in here. No owner credentials are needed for session practice.</p><button class="btn" data-action="close-modal">Continue in practice mode</button>');return;}if(connected()){setView('settings');return;}modal(`<h2>Connect your Command Center.</h2><p>Use your existing Persen owner account. Donna checks the admin allowlist before retrieving business records.</p><form id="login-form"><div class="field"><label for="email">Email address</label><input id="email" type="email" name="email" autocomplete="username" required></div><div class="field"><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password" required></div><div class="live-region" role="status" id="login-status"></div><div class="form-actions"><button class="btn primary" type="submit">Connect securely</button><button type="button" class="btn" data-action="close-modal">Cancel</button></div></form>`);}
async function sendMessage(text){
 if(!text.trim()||state.busy||state.sending)return;
 const generation=state.generation,conversationEpoch=state.conversationEpoch;state.busy=true;state.sending=true;
 state.messages.push({role:'user',text:text.trim(),at:new Date().toISOString()});
 if(connected()&&/order|priorit|task|stock|invent|brief|invoice|money|owe|payment|agreement|event/i.test(text))await loadRecords();
 if(generation!==state.generation||conversationEpoch!==state.conversationEpoch)return;
 let answer;
 if(state.teaching&&!/cancel|never mind/i.test(text)){
   state.teachingDraft=text.trim();state.teaching=false;
   answer={text:'Thank you. I’ve kept your words as a teaching draft. Tap “Review teaching draft” to give it a title and prepare it for approval. Nothing has been added to confirmed memory yet.'};
 }else if(/\b(teach|remember)\b/i.test(text)){
   if(text.length<85&&!/that|when|always|process is/i.test(text)){state.teaching=true;answer={text:'Of course. Tell me the process or preference in your own words. What should I know, and when should I use it? I’ll help you prepare a draft, then you can review it before I remember.'};}
   else{state.teachingDraft=text.trim();answer={text:'I’ve prepared your teaching draft. Before remembering it, let’s review the exact wording and its source. Tap “Review teaching draft” below.'};}
 }else{state.teaching=false;try{answer=answerMessage(text,{data:state.data,memories:memories().filter(m=>m.status==='confirmed'),now:new Date()});}catch{answer={text:'Let’s take that one step at a time. You can open priorities, check pricing, or teach me a business process. I could not complete that lookup just now.'};}}
 state.messages.push({role:'assistant',text:answer.text,at:new Date().toISOString()});state.messages=state.messages.slice(-200);saveSession();
 if(connected())try{const conversation=await api.conversations.save({id:state.conversationId||undefined,title:state.conversationTitle||state.messages.find(m=>m.role==='user')?.text.slice(0,80)||'Donna conversation',messages:state.messages});if(generation!==state.generation||conversationEpoch!==state.conversationEpoch)return;state.conversationId=conversation.id;state.conversationTitle=conversation.title||state.conversationTitle;}catch{if(generation!==state.generation||conversationEpoch!==state.conversationEpoch)return;toast('Conversation is in this tab only. Private conversation storage is not ready.');}
 if(generation!==state.generation||conversationEpoch!==state.conversationEpoch)return;state.busy=false;state.sending=false;render();if(!state.settings.voiceMuted&&(state.settings.speak||state.view==='voice'))speak(answer.text);
}
function newConversation(){
 if(state.sending){toast('Please wait for this reply before starting another conversation.');return;}
 state.conversationEpoch++;state.conversationId=null;state.conversationTitle='';state.messages=[];
 state.teaching=false;state.teachingDraft=null;stopListening();cancelSpeech();
 saveSession();if(!['chat','voice'].includes(state.view))setView('chat');else render();
 toast(connected()?'A fresh conversation is ready. Your saved conversations remain in the library.':'A fresh session conversation is ready. Earlier practice messages have been cleared.');
}
async function savedConversations(){
 if(state.sending)return;
 if(!connected()){
  modal('<h2>Your session conversation.</h2><p>Practice messages stay in this browser tab. There is no cloud conversation archive in practice mode. Export your data before clearing this tab if you want to keep it.</p><div class="form-actions"><button class="btn" data-action="export">Export session data</button><button class="btn" data-action="close-modal">Continue conversation</button></div>');
  return;
 }
 const generation=state.generation,conversationEpoch=state.conversationEpoch;
 modal('<h2>Saved conversations</h2><p role="status">Loading your private conversation list…</p><button class="btn" data-action="close-modal">Cancel</button>');
 const dialogEpoch=state.dialogEpoch;
 try{
  const result=await api.conversations.list();
  if(generation!==state.generation||conversationEpoch!==state.conversationEpoch||dialogEpoch!==state.dialogEpoch||!connected())return;
  const list=[...result.rows].sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)));
  modal(`<h2>Saved conversations</h2><p>Choose a transcript to continue. Opening it only displays saved text; it never replays actions or sends a message.${result.complete?'':' This is a partial list.'}</p>${list.length?list.map(c=>`<div class="version"><strong>${esc(c.title)}</strong><div class="small muted">${esc(new Date(c.updated_at).toLocaleString())}</div><button class="btn" style="margin-top:10px" data-action="open-conversation" data-id="${esc(c.id)}">Open conversation ${icon('arrow')}</button></div>`).join(''):'<p>No saved conversations yet. New replies will be saved here once private conversation storage is installed.</p>'}<button class="btn" data-action="close-modal">Close</button>`);
 }catch(error){
  if(generation!==state.generation||dialogEpoch!==state.dialogEpoch||!connected())return;
  modal(`<h2>Conversation storage is not ready.</h2><p>${esc(error.message)}</p><p>Your current transcript is still available in this tab.</p><button class="btn" data-action="close-modal">Continue conversation</button>`);
 }
}
async function openConversation(id){
 if(!connected()||state.sending)return;
 const generation=state.generation,conversationEpoch=++state.conversationEpoch;
 modal('<h2>Opening your conversation…</h2><p role="status">Reading the transcript for your signed-in account.</p><button class="btn" data-action="close-modal">Cancel</button>');
 const dialogEpoch=state.dialogEpoch;
 try{
  const conversation=await api.conversations.get(id);
  if(generation!==state.generation||conversationEpoch!==state.conversationEpoch||dialogEpoch!==state.dialogEpoch||!connected())return;
  state.messages=conversation.messages.map(m=>({role:m.role,text:m.text,at:m.at}));
  state.conversationId=conversation.id;state.conversationTitle=conversation.title;
  state.teaching=false;state.teachingDraft=null;closeModal();saveSession();
  if(!['chat','voice'].includes(state.view))setView('chat');else render();
  toast('Transcript restored. No messages or business actions were replayed.');
 }catch(error){
  if(generation!==state.generation||conversationEpoch!==state.conversationEpoch||dialogEpoch!==state.dialogEpoch||!connected())return;
  modal(`<h2>I couldn’t open that transcript.</h2><p>${esc(error.message)}</p><button class="btn" data-action="close-modal">Close</button>`);
 }
}
function saveSettings(){try{browserStorage('localStorage')?.setItem('donna.settings',JSON.stringify(state.settings));}catch{}document.documentElement.dataset.theme=state.settings.theme;}
let activeUtterance=null;
function cancelSpeech(){activeUtterance=null;window.speechSynthesis?.cancel();}
function speak(text){if(!window.speechSynthesis){toast('Speech playback is unavailable. Your transcript is ready to read.');return;}cancelSpeech();const u=new SpeechSynthesisUtterance(text);activeUtterance=u;const voice=speechSynthesis.getVoices().find(v=>v.voiceURI===state.settings.voice);if(voice)u.voice=voice;u.rate=.96;u.onstart=()=>{if(activeUtterance!==u)return;const status=$('#voice-status');if(status)status.textContent='Donna is speaking. Tap Stop speaking to interrupt.';};u.onend=()=>{if(activeUtterance!==u)return;activeUtterance=null;const status=$('#voice-status');if(status)status.textContent='Ready for your next question.';};u.onerror=e=>{if(activeUtterance!==u)return;activeUtterance=null;if(e.error!=='canceled'&&e.error!=='interrupted')toast('Playback did not complete. Tap Play reply to try again, or read the transcript.');const status=$('#voice-status');if(status)status.textContent='Audio stopped. You can tap Play reply to try again.';};speechSynthesis.speak(u);}
let recognition;
function stopListening(){try{recognition?.stop();}catch{}state.listening=false;}
function startListening(){if(state.listening){stopListening();render();return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Browser speech input is unavailable. Tap the microphone on your iPhone keyboard to dictate.');return;}modal(`<h2>Use browser voice input?</h2><p>Your browser or operating system may process audio using its speech service. Donna cannot guarantee browser transcription stays on your device. Use keyboard dictation, or the native app’s checked on-device mode, if you prefer.</p><div class="form-actions"><button class="btn primary" data-action="confirm-mic">Start voice input</button><button class="btn" data-action="close-modal">Use text instead</button></div>`);}
function beginRecognition(){closeModal();try{cancelSpeech();const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;recognition=new Recognition();const activeRecognition=recognition,recognitionView=state.view;recognition.lang='en-US';recognition.continuous=false;recognition.interimResults=false;recognition.onresult=e=>{if(recognition!==activeRecognition||state.view!==recognitionView)return;const text=e.results[0][0].transcript;const input=$('#chat-form textarea')||$('#lesson');if(input){input.value=text;input.focus();if(state.view==='voice'&&input.closest('#chat-form')&&!state.sending&&!state.busy){toast('Sending your voice message…');sendMessage(text).catch(()=>toast('Unable to send. Your transcript remains visible for review.'));}else toast('Transcript ready. Review it, then send.');}};recognition.onerror=e=>{if(recognition!==activeRecognition||e.error==='aborted'||state.view!==recognitionView)return;state.listening=false;toast(e.error==='not-allowed'?'Microphone permission was denied. Keyboard dictation is still available.':'Speech input stopped: '+e.error);render();};recognition.onend=()=>{if(recognition!==activeRecognition||state.view!==recognitionView)return;state.listening=false;const b=$('[data-action="mic"]');if(b){b.classList.remove('listening');if(state.view==='voice'){b.setAttribute('aria-pressed','false');b.setAttribute('aria-label','Start voice input');}}const label=$('#voice-status');if(label&&state.view==='voice'&&!state.sending&&!state.busy)label.textContent='Ready for your next question.';};recognition.start();state.listening=true;const b=$('[data-action="mic"]');if(b){b.classList.add('listening');if(state.view==='voice'){b.setAttribute('aria-pressed','true');b.setAttribute('aria-label','Finish voice input');}}const label=$('#voice-status');if(label)label.textContent='Listening… tap to finish.';}catch(e){toast('Voice input is unavailable here. Use keyboard dictation.');}}
async function refreshMemories(){const generation=state.generation;if(connected()){const result=await api.memories.list();if(generation!==state.generation||!connected())return;state.memories=result.rows;state.memoryComplete=result.complete;}saveSession();render();}
async function memoryAction(action,id){const m=memories().find(x=>x.id===id);if(!m)return;if(action==='history'){let h=m.history||[];if(connected())try{h=await api.memories.history(id);}catch(e){toast(e.message);return;}modal(`<h2>Memory history</h2><p>${esc(m.title)} · Current version ${esc(m.version||1)}</p>${h.length?h.map(v=>`<div class="version">${esc(typeof v==='object'?JSON.stringify(v,null,2):v)}</div>`).join(''):'<p>No previous versions.</p>'}<button class="btn" data-action="close-modal">Close</button>`);return;}if(action==='approve'||action==='delete'||action==='outdated'){modal(`<h2>${action==='approve'?'Approve this memory?':action==='delete'?'Delete this memory?':'Mark this memory outdated?'}</h2><p><strong>${esc(m.title)}</strong></p><div class="version">${esc(m.content)}</div><p>${action==='approve'?'I’ll use this as confirmed business knowledge. Please check the exact wording.':action==='delete'?'This removes the memory and its history.':'I’ll keep the history, and stop using this as a current fact.'}</p><div class="form-actions"><button class="btn ${action==='delete'?'danger':'primary'}" data-memory-confirm="${action}" data-id="${esc(id)}">${action==='approve'?'Approve & remember':action==='delete'?'Delete memory':'Mark outdated'}</button><button class="btn" data-action="close-modal">Cancel</button></div>`);return;}if(action==='edit')modal(`<h2>Let’s get this right.</h2><p>Corrections create a new version and return the memory to a draft for your review.</p><form id="edit-memory-form" data-id="${esc(id)}"><div class="field"><label for="edit-title">Title</label><input name="title" id="edit-title" value="${esc(m.title)}" maxlength="160" required></div><div class="field"><label for="edit-content">Procedure or information</label><textarea name="content" id="edit-content" maxlength="6000" required>${esc(m.content)}</textarea></div><div class="form-actions"><button class="btn primary">Save correction as draft</button><button class="btn" type="button" data-action="close-modal">Cancel</button></div></form>`);}
async function mutateMemory(id,patch,remove=false){if(connected()){if(remove)await api.memories.delete(id);else await api.memories.update(id,{...patch,version:state.memories.find(m=>m.id===id)?.version});}else{const i=state.localMemories.findIndex(m=>m.id===id);if(i<0)return;if(remove)state.localMemories.splice(i,1);else{const m=state.localMemories[i];const history=[...(m.history||[]),{title:m.title,content:m.content,status:m.status,version:m.version,at:m.updated_at}];state.localMemories[i]={...m,...patch,history,version:(m.version||1)+1,updated_at:new Date().toISOString()};}}await refreshMemories();}
function plannerModal(kind){const event=kind==='event';modal(`<h2>${event?'Make space for an event.':'What’s your next small step?'}</h2><p>This plan stays in this browser session. No business records or calendar are changed.</p><form id="planner-form" data-kind="${kind}"><div class="field"><label for="plan-title">${event?'Event':'Task'}</label><input id="plan-title" name="title" required maxlength="180"></div><div class="field"><label for="plan-date">${event?'Date':'Due date (optional)'}</label><input id="plan-date" name="date" type="date" ${event?'required':''}></div>${event?'<div class="field"><label for="plan-notes">Notes</label><textarea name="notes" id="plan-notes" maxlength="1000"></textarea></div>':'<div class="field"><label for="priority">Priority</label><select name="priority" id="priority"><option>Normal</option><option>High</option><option>Low</option></select></div>'}<div class="form-actions"><button class="btn primary" type="submit">Add to my session plan</button><button class="btn" type="button" data-action="close-modal">Cancel</button></div></form>`);}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportEvent(id){const e=state.events.find(e=>e.id===id);if(!e)return;const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&').replace(/\r/g,'');const end=new Date(e.date+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);const body=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Persen Apparel//Donna//EN','BEGIN:VEVENT',`UID:${e.id}@donna.persenapparel.com`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').split('.')[0]}Z`,`DTSTART;VALUE=DATE:${e.date.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${end.toISOString().slice(0,10).replace(/-/g,'')}`,`SUMMARY:${clean(e.title)}`,`DESCRIPTION:${clean(e.notes)}`,'END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n';download('donna-event.ics',body,'text/calendar');toast('Calendar file prepared. Review it before adding it to your calendar.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-view],[data-action],[data-prompt],[data-memory],[data-memory-confirm],[data-remove-task],[data-remove-event],[data-export-event]');if(!b)return;try{if(b.dataset.view){e.preventDefault();setView(b.dataset.view);return;}if(b.dataset.prompt){await sendMessage(b.dataset.prompt);return;}if(b.dataset.memory){await memoryAction(b.dataset.memory,b.dataset.id);return;}if(b.dataset.memoryConfirm){const a=b.dataset.memoryConfirm;await mutateMemory(b.dataset.id,a==='approve'?{status:'confirmed',approved:true}:{status:'outdated'},a==='delete');closeModal();toast(a==='approve'?'Got it. I’ll remember this as approved knowledge.':'Memory updated.');return;}if(b.dataset.removeTask){state.tasks=state.tasks.filter(t=>t.id!==b.dataset.removeTask);saveSession();render();return;}if(b.dataset.removeEvent){state.events=state.events.filter(t=>t.id!==b.dataset.removeEvent);saveSession();render();return;}if(b.dataset.exportEvent){exportEvent(b.dataset.exportEvent);return;}const action=b.dataset.action;if(action==='copy-private-chat-prompt'){await copyPrivateChatPrompt();return;}if(action==='new-conversation'){newConversation();return;}if(action==='saved-conversations'){await savedConversations();return;}if(action==='open-conversation'){await openConversation(b.dataset.id);return;}if(action==='menu'){const side=$('.sidebar');side.classList.toggle('open');b.setAttribute('aria-expanded',side.classList.contains('open'));}if(action==='login')loginModal();if(action==='review-teaching'){setView('teach');$('#lesson').value=state.teachingDraft||'';$('#memory-title').focus();}if(action==='close-modal')closeModal();if(action==='theme'){state.settings.theme=state.settings.theme==='dark'?'light':'dark';saveSettings();render();}if(action==='refresh'){if(!connected())loginModal();else await loadRecords();}if(action==='mic')startListening();if(action==='confirm-mic')beginRecognition();if(action==='test-voice')speak('Hey! What can I help you with today?');if(action==='speak-last'){const last=[...state.messages].reverse().find(m=>m.role==='assistant');if(last)speak(last.text);else speak('Hey! What can I help you with today?');}if(action==='toggle-voice-mute'){state.settings.voiceMuted=!state.settings.voiceMuted;saveSettings();if(state.settings.voiceMuted)cancelSpeech();render();const status=$('#voice-status');if(status)status.textContent=state.settings.voiceMuted?'Automatic replies muted. Tap Unmute replies to hear Donna again.':'Automatic replies enabled.';}if(action==='stop-speech'){cancelSpeech();const status=$('#voice-status');if(status)status.textContent='Speech stopped. Tap Play reply to hear it again, or tap the microphone to ask another question.';}if(action==='add-task')plannerModal('task');if(action==='add-event')plannerModal('event');if(action==='export'){const data=connected()?await api.exportData():{memories:state.localMemories,conversations:state.messages,tasks:state.tasks,events:state.events};download('donna-private-export.json',JSON.stringify(data,null,2));toast('Private export prepared. Store it somewhere secure.');}if(action==='delete-data')modal('<h2>Delete Donna’s saved data?</h2><p>This deletes Donna conversations and memories for your account, plus this session’s plans. It does not change your business records.</p><div class="field"><label for="delete-phrase">Type DELETE MY DONNA DATA to confirm</label><input id="delete-phrase" autocomplete="off"></div><div class="form-actions"><button class="btn danger" data-action="confirm-delete-data">Delete Donna data</button><button class="btn" data-action="close-modal">Cancel</button></div>');if(action==='confirm-delete-data'){if(connected()){const phrase=$('#delete-phrase')?.value;if(phrase!=='DELETE MY DONNA DATA'){toast('Type DELETE MY DONNA DATA to confirm.');return;}await api.deleteData(phrase);}state.messages=[];state.conversationId=null;state.conversationTitle='';state.conversationEpoch++;state.localMemories=[];state.memories=[];state.tasks=[];state.events=[];saveSession();closeModal();render();toast('Donna data deleted.');}if(action==='signout'){
 state.generation++;state.conversationEpoch++;closeModal();$('#modal-content').replaceChildren();const logout=api.signOut();
 state.busy=false;state.sending=false;state.conversationTitle='';state.teaching=false;state.teachingDraft=null;state.conversationId=null;
 state.auth={authenticated:false,admin:false};state.data={};state.errors={};state.memories=[];state.messages=[];
 try{browserStorage('sessionStorage')?.removeItem('donna.sandbox');}catch{}
 stopListening();cancelSpeech();render();
 try{await logout;toast('Signed out. Business records have been cleared from this view.');}catch{toast('Local access cleared. The remote logout could not be reached.');}
}}catch(err){toast(err.message||'Something didn’t complete. Please try again.');}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));try{if(f.id==='login-form'){const status=$('#login-status');status.textContent='Checking your owner account…';f.querySelector('[type=submit]').disabled=true;try{await api.signIn(data.email,data.password);state.auth=await api.status();state.generation++;if(!connected())throw Error('Your account is not on the owner allowlist.');state.messages=[];state.conversationId=null;state.conversationTitle='';state.conversationEpoch++;saveSession();closeModal();await loadRecords();toast('You’re connected. I’ll keep your business records read-only.');}catch(err){status.textContent=err.message;f.querySelector('[type=submit]').disabled=false;}return;}if(f.id==='chat-form'){const text=data.message;f.reset();await sendMessage(text);return;}if(f.id==='teach-form'){let m;if(connected()){m=await api.memories.create(data);}else{const now=new Date().toISOString();m={...data,id:crypto.randomUUID(),status:'pending',version:1,history:[],created_at:now,updated_at:now};state.localMemories.push(m);}state.teachingDraft=null;state.teaching=false;await refreshMemories();setView('memory');toast('I’ve prepared a draft. Please review it before I remember it.');return;}if(f.id==='edit-memory-form'){await mutateMemory(f.dataset.id,{title:data.title,content:data.content,status:'pending'});closeModal();toast('Correction prepared. Please approve this new version.');return;}if(f.id==='planner-form'){const item={id:crypto.randomUUID(),title:data.title,date:data.date,notes:data.notes,priority:data.priority,done:false,due:data.date};if(f.dataset.kind==='event')state.events.push(item);else state.tasks.push(item);saveSession();closeModal();render();return;}if(f.id==='pricing-form'){const r=calculatePricing(data);$('#pricing-result').innerHTML=`<div class="result"><h3>Here’s what your numbers say.</h3><div class="result-grid">${[['Cost per unit',money(r.unitCostCents)],['Profit per unit',money(r.unitProfitCents)],['Profit margin',r.marginPercent==null?'—':r.marginPercent.toFixed(1)+'%'],['Total revenue',money(r.revenueCents)],['Total cost',money(r.totalCostCents)],['Estimated profit',money(r.profitCents)]].map(([label,v])=>`<div><span>${label}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p>${esc(r.warning||'This estimate includes only the costs you entered. Check the inputs before making a purchase or quoting a customer.')}</p></div>`;return;}}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='voice-select'){state.settings.voice=el.value;saveSettings();}if(el.id==='speak-toggle'){state.settings.speak=el.checked;saveSettings();if(!el.checked)cancelSpeech();}if(el.id==='theme-select'){state.settings.theme=el.value;saveSettings();}if(el.dataset.task){const t=state.tasks.find(x=>x.id===el.dataset.task);if(t)t.done=el.checked;saveSession();render();}});
document.addEventListener('input',e=>{if(!['memory-search','record-search'].includes(e.target.id))return;state.search=e.target.value;const pos=e.target.selectionStart;const id=e.target.id;render();const input=$('#'+id);input?.focus();input?.setSelectionRange(pos,pos);});
document.addEventListener('keydown',e=>{if(e.target.matches('#chat-form textarea')&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit();}});
$('#modal').addEventListener('cancel',()=>{state.dialogEpoch++;});
window.addEventListener('popstate',()=>{state.view=new URLSearchParams(location.search).get('view')||'overview';render();});
window.addEventListener('pagehide',()=>{stopListening();cancelSpeech();});
window.speechSynthesis?.addEventListener('voiceschanged',()=>{if(state.view==='settings')render();});
render();
try{state.auth=await api.status();if(connected()){state.messages=[];saveSession();await loadRecords();}else render();}catch{state.auth={authenticated:false,admin:false};render();}
